text:
Here's your water tracker with a goal of 8 glasses. Tap + after each glass, and it resets each day if your screen allows saving.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body { font-family: system-ui, sans-serif; text-align: center; padding: 24px; margin: 0; }
  h1 { font-size: 20px; margin: 0 0 16px; }
  .ring { width: 160px; height: 160px; border-radius: 50%; margin: 0 auto 16px; display: flex; align-items: center; justify-content: center; font-size: 32px; font-weight: 600; }
  .glasses { font-size: 28px; letter-spacing: 4px; min-height: 40px; margin-bottom: 16px; }
  button { font-size: 22px; padding: 10px 22px; margin: 0 6px; border-radius: 10px; border: 1px solid #888; cursor: pointer; }
  #msg { margin-top: 16px; min-height: 24px; }
  #reset { font-size: 14px; margin-top: 20px; }
</style>
</head>
<body>
  <h1>Water today</h1>
  <div class="ring" id="ring"><span id="count">0 / 8</span></div>
  <div class="glasses" id="glasses"></div>
  <div>
    <button id="minus">−</button>
    <button id="plus">+</button>
  </div>
  <div id="msg"></div>
  <button id="reset">Reset</button>
<script>
  var GOAL = 8;
  var today = new Date().toDateString();
  var n = 0;
  try {
    var saved = JSON.parse(localStorage.getItem("water") || "{}");
    if (saved.day === today) n = saved.n || 0;
  } catch (e) {}
  function save() {
    try { localStorage.setItem("water", JSON.stringify({ day: today, n: n })); } catch (e) {}
  }
  function draw() {
    var pct = Math.min(n / GOAL, 1) * 360;
    document.getElementById("ring").style.background =
      "conic-gradient(#2a8de0 " + pct + "deg, #ddd 0deg)";
    document.getElementById("count").textContent = n + " / " + GOAL;
    document.getElementById("count").style.cssText =
      "background:#fff;border-radius:50%;width:120px;height:120px;display:flex;align-items:center;justify-content:center;color:#222";
    var g = "";
    for (var i = 0; i < GOAL; i++) g += i < n ? "💧" : "○";
    document.getElementById("glasses").textContent = g;
    document.getElementById("msg").textContent =
      n >= GOAL ? "Goal reached. Well done!" : (GOAL - n) + " more to go";
  }
  document.getElementById("plus").onclick = function () { n++; save(); draw(); };
  document.getElementById("minus").onclick = function () { if (n > 0) n--; save(); draw(); };
  document.getElementById("reset").onclick = function () { n = 0; save(); draw(); };
  draw();
</script>
</body>
</html>
```
